@Suppress("UNCHECKED_CAST")
fun testJoseVectors() {
    val v = PyreonAuthJson.obj(VECTORS) ?: error("vectors.json is readable")
    val keys = v["keys"] as List<Map<String, Any?>>
    val cases = v["cases"] as List<Map<String, Any?>>
    check(cases.size >= 30) { "vector set is complete (${cases.size})" }
    for (c in cases) {
        val got = try {
            PyreonJose.verifyIdToken(
                c["token"] as String, keys, v["issuer"] as String, v["clientId"] as String,
                c["nonce"] as? String, v["now"] as Double,
            )
            "ok"
        } catch (e: PyreonAuthError) {
            e.code
        }
        check(got == c["expect"]) { "vector \"${c["name"]}\": expected ${c["expect"]}, got $got" }
    }
}

fun testStrictBase64url() {
    check(PyreonJose.decodeBase64url("QUJD")?.toString(Charsets.UTF_8) == "ABC") { "decodes" }
    for (bad in listOf("QUJD=", "QU JD", "QUJ+", "QUJ/", "Q", "QR")) {
        check(PyreonJose.decodeBase64url(bad) == null) { "rejects \"$bad\"" }
    }
}

fun main() {
    testJoseVectors()
    testStrictBase64url()
    println("[PyreonOidcJoseTest] all smoke tests passed")
}
